#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> a(3), b(3);
    for (int i = 0; i < 3; i++) cin >> a[i];
    for (int i = 0; i < 3; i++) cin >> b[i];

    int max_val = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);

    vector<vector<int>> orders = {
        {0, 1, 2},
        {2, 1, 0},
        {1, 2, 0},
        {0, 2, 1},
        {2, 0, 1},
        {1, 0, 2}
    };

    int minSum = INT_MAX;
    for (auto &order : orders) {
        vector<int> A = a;
        vector<int> B = b;
        int sum = 0;
        for (int idx : order) {
            int bIdx = (idx + 1) % 3;
            int minVal = min(A[idx], B[bIdx]);
            A[idx] -= minVal;
            B[bIdx] -= minVal;
            sum += A[idx];
        }
        minSum = min(minSum, sum);
    }

    cout << minSum << " " << max_val << "\n";
    return 0;
}
